const TICKER_DIRECTORY = {
  TW: TICKER_DIRECTORY_RAW.TW.map(([code, name]) => ({ code, name })),
  US: TICKER_DIRECTORY_RAW.US.map(([code, name]) => ({ code, name })),
};

const TICKER_NAME_LOOKUP = {
  TW: new Map(TICKER_DIRECTORY_RAW.TW),
  US: new Map(TICKER_DIRECTORY_RAW.US),
};

// Company name for a market + ticker, or '' when it isn't in the directory.
window.tickerName = (market, code) => (TICKER_NAME_LOOKUP[market] && TICKER_NAME_LOOKUP[market].get(code)) || '';
window.TickerDirectory = TICKER_DIRECTORY;
